  --lab:"Archivo Narrow","Arial Narrow",sans-serif;
  --prose:"Source Sans 3",-apple-system,BlinkMacSystemFont,"Segoe UI",Helvetica,Arial,sans-serif;
}
*{box-sizing:border-box}
html{-webkit-print-color-adjust:exact;print-color-adjust:exact}
body{margin:0;background:var(--desk);color:var(--ink);font-family:var(--prose);
  font-size:11pt;line-height:1.5;-webkit-font-smoothing:antialiased}

/* --------------------------------------------------------------- the sheet */
.stack{display:flex;flex-direction:column;align-items:center;gap:26px;padding:26px 12px 60px}
.sheet{
  position:relative;width:8.5in;min-height:11in;background:var(--paper);
  padding:0.5in 0.5in 0.5in 0.86in;
  box-shadow:0 6px 20px rgba(20,28,24,.26);
}
/* punched rail — a material of the paper, drawn not decorated */
.sheet::before{
  content:"";position:absolute;left:0;top:0;bottom:0;width:0.62in;
  border-right:1px solid var(--rule-hair);
  background-image:radial-gradient(circle at 0.31in 0.9in, var(--desk) 0 0.085in, transparent 0.087in),
                   radial-gradient(circle at 0.31in 50%,   var(--desk) 0 0.085in, transparent 0.087in),
                   radial-gradient(circle at 0.31in calc(100% - 0.9in), var(--desk) 0 0.085in, transparent 0.087in);
  background-repeat:no-repeat;
}
.sheetno{position:absolute;right:0.5in;bottom:0.3in;font-family:var(--mono);
  font-size:7.5pt;color:var(--ink-3);letter-spacing:.06em}
.contfoot{position:absolute;left:0.86in;bottom:0.3in;font-family:var(--lab);
  font-size:7.5pt;color:var(--ink-3);letter-spacing:.14em;text-transform:uppercase}

/* ------------------------------------------------------------- chart header */
.chdr{border:1.5px solid var(--ink);margin-bottom:16px}
---print media---
/* ----------------------------------------------------------------- legend */
.legend{display:flex;gap:20px;flex-wrap:wrap;align-items:center;margin-top:9px;
  font-family:var(--mono);font-size:7.5pt;color:var(--ink-2);letter-spacing:.03em}
.legend span{display:flex;align-items:center;gap:6px}
.foot{margin-top:20px;padding-top:8px;border-top:1px solid var(--rule);
  font-family:var(--mono);font-size:7.5pt;color:var(--ink-3);line-height:1.75}
.protonote{width:8.5in;max-width:100%;font-family:var(--lab);font-size:8.5pt;
  letter-spacing:.16em;text-transform:uppercase;color:#3c443f}

@media print{
  body{background:#fff}
  .stack{gap:0;padding:0}
  .sheet{box-shadow:none;margin:0;page-break-after:always}
  .sheet:last-child{page-break-after:auto}
  .protonote{display:none}
  .sheet::before{background-image:radial-gradient(circle at 0.31in 0.9in, #fff 0 0.085in, transparent 0.087in),
                   radial-gradient(circle at 0.31in 50%, #fff 0 0.085in, transparent 0.087in),
                   radial-gradient(circle at 0.31in calc(100% - 0.9in), #fff 0 0.085in, transparent 0.087in)}
}
@page{size:letter;margin:0}
@media screen and (max-width:9in){
  .sheet{width:100%;min-height:0;padding:22px 20px 34px 46px}
  .sheet::before{width:30px}
  .cols{grid-template-columns:1fr}
  .rows td.trk{width:auto}
}
:focus-visible{outline:2px solid var(--obs);outline-offset:2px}
</style>

<div class="stack">
  <div class="protonote" id="protonote"></div>

  <!-- ================================================== SHEET 1 -->
  <section class="sheet">
    <div class="chdr">
      <div class="rowa">

